/**
 * Recrify logo mark (frontend/public/logo-mark@512.png) embedded as a base64
 * data URI so the server-rendered PDF report is fully self-contained — no
 * runtime file read or network fetch, works in dev and in the compiled build.
 * Regenerate: base64 -i frontend/public/logo-mark@512.png
 */
export const RECRIFY_LOGO_DATA_URI =
  'data:image/png;base64,';
